INSERT INTO public.person (id, name, aliases, era, birth_year, death_year, description, biography, status)
SELECT id, name, aliases, era, birth_year, death_year, description, biography, status FROM jsonb_populate_recordset(NULL::public.person, '[{"name": "张郁", "aliases": [], "era": "晚唐", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷256光启二年条所见人物：张郁。", "biography": null, "status": "draft", "id": "bbe54f2e-a63a-5383-a1e5-532893a3032c"}, {"name": "李克用", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": 908, "description": "河东晋王，李存勖之父。908年去世，临终命李存勖继承军府。此处的晋不等于后来的后晋。", "biography": "河东晋王，李存勖之父。908年去世，临终命李存勖继承军府。此处的晋不等于后来的后晋。", "status": "draft", "id": "04af206e-fa86-581c-86b9-87a78a8d59a5"}, {"name": "王重荣", "aliases": [], "era": "晚唐", "birth_year": null, "death_year": null, "description": "晚唐河中节度使；882年朱温举同州归附，王重荣接纳并上奏。", "biography": "晚唐河中节度使；882年朱温举同州归附，王重荣接纳并上奏。", "status": "draft", "id": "fc935d86-e44a-538d-b21b-6e28a8604116"}, {"name": "田令孜", "aliases": [], "era": "晚唐", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷255中和四年记载的田令孜：担忧杨师立作乱。", "biography": null, "status": "draft", "id": "5080b636-4944-5887-afed-2195aeb4a567"}, {"name": "杨复恭", "aliases": [], "era": "晚唐", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷256中和四年条所见人物：杨复恭。", "biography": null, "status": "draft", "id": "d84e65f4-4bf5-58ad-a8c6-d69729edbc51"}, {"name": "杜让能", "aliases": [], "era": "晚唐", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷256光启二年条所见人物：杜让能。", "biography": null, "status": "draft", "id": "e3eae55f-2032-5c76-905f-e480ad32ea69"}, {"name": "孔纬", "aliases": [], "era": "晚唐", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷256光启二年条所见人物：孔纬。", "biography": null, "status": "draft", "id": "07254f47-15dc-55d0-b38f-bfefa4def94e"}, {"name": "朱玫", "aliases": [], "era": "晚唐", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷256光启元年条所见人物：朱玫。", "biography": null, "status": "draft", "id": "bb37d3e7-f348-51ea-bc68-8b4355399a19"}, {"name": "李昌符", "aliases": [], "era": "晚唐", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷256中和四年条所见人物：李昌符。", "biography": null, "status": "draft", "id": "40f447e6-4770-5e94-9e87-b48375844b3d"}, {"name": "萧遘", "aliases": [], "era": "晚唐", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷256光启二年条所见人物：萧遘。", "biography": null, "status": "draft", "id": "4eb0a98d-80ed-52f0-9e2c-2a84e77f2147"}, {"name": "李松年", "aliases": [], "era": "晚唐", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷256光启二年条所见人物：李松年。", "biography": null, "status": "draft", "id": "237f05ec-5473-5694-b643-ba1f16dcdeb6"}, {"name": "裴澈", "aliases": [], "era": "晚唐", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷256光启二年条所见人物：裴澈。", "biography": null, "status": "draft", "id": "218df366-f371-537f-8710-a07a8460f214"}, {"name": "杨晟", "aliases": [], "era": "晚唐", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷256光启二年条所见人物：杨晟。", "biography": null, "status": "draft", "id": "93faf005-49ad-5fd8-82c5-75a556805ef0"}, {"name": "王建", "aliases": [], "era": "唐末五代十国", "birth_year": null, "death_year": null, "description": "据《资治通鉴》，907年在“蜀王与晋王讨论讨梁及称帝”中为致书提议者。", "biography": null, "status": "draft", "id": "b02193d6-1c17-5154-bb7c-3295ed8dbbec"}, {"name": "晋晖", "aliases": [], "era": "晚唐", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷256中和四年条所见人物：晋晖。", "biography": null, "status": "draft", "id": "60d1489b-54e7-5af8-a534-7ad27c3dfeb2"}, {"name": "李煴", "aliases": ["嗣襄王煴"], "era": "晚唐", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷256光启二年条所见人物：李煴。", "biography": null, "status": "draft", "id": "1cdc1b9d-e9a6-55fd-b6ea-016b483c2f3d"}, {"name": "朱政", "aliases": [], "era": "晚唐", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷256光启二年条所见人物：朱政。", "biography": null, "status": "draft", "id": "1dbb1ccc-8b08-5a32-8209-1406ed16dd1c"}, {"name": "郑从谠", "aliases": [], "era": "晚唐", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷256光启二年条所见人物：郑从谠。", "biography": null, "status": "draft", "id": "15f99f06-f58e-5b7f-8845-549c1edaad2d"}, {"name": "石君涉", "aliases": [], "era": "晚唐", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷256光启二年条所见人物：石君涉。", "biography": null, "status": "draft", "id": "13186c18-f743-5d26-a4c6-980e09583665"}]'::jsonb)
ON CONFLICT (id) DO NOTHING;

INSERT INTO public.event (id, title, start_year, end_year, time_original, dynasty, description, phases, location_name, location_modern_name, location_lat, location_lng, location_precision, location_note, status)
SELECT id, title, start_year, end_year, time_original, dynasty, description, phases, location_name, location_modern_name, location_lat, location_lng, location_precision, location_note, status FROM jsonb_populate_recordset(NULL::public.event, '[{"title": "张郁作乱并攻陷常州", "start_year": 886, "end_year": 886, "time_original": "光启二年春正月", "dynasty": "唐", "description": "镇海牙将张郁作乱，攻陷常州。", "phases": [], "location_name": "常州", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "c0fac5aa-425c-5e82-8a4e-b47cca154fd5"}, {"title": "李克用、王重荣上表请僖宗还宫并诛田令孜", "start_year": 886, "end_year": 886, "time_original": "光启二年正月条；具体日未载", "dynasty": "唐", "description": "李克用回军河中，与王重荣共同上表，请皇帝回宫，并列田令孜罪状、请求诛杀。", "phases": [], "location_name": "河中、行在", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "5ce84e09-d791-557c-94ca-e7f58659d1e5"}, {"title": "杨复恭复任枢密使", "start_year": 886, "end_year": 886, "time_original": "光启二年正月条；具体日未载", "dynasty": "唐", "description": "朝廷再次任飞龙使杨复恭为枢密使。", "phases": [], "location_name": null, "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "原文未给单一地点。", "status": "draft", "id": "9c837f50-8667-5230-a801-605707cbb0b0"}, {"title": "田令孜劫持僖宗出奔宝鸡", "start_year": 886, "end_year": 886, "time_original": "光启二年正月戊子夜", "dynasty": "唐", "description": "田令孜请求皇帝往兴元，皇帝不从；当夜田令孜领兵入宫，迫使车驾往宝鸡，朝臣多不知情。", "phases": [], "location_name": "凤翔、宝鸡", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "b11b9266-3221-54a1-b260-9afa0c410df5"}, {"title": "杜让能、孔纬等追及车驾", "start_year": 886, "end_year": 886, "time_original": "戊子夜后至翌日", "dynasty": "唐", "description": "杜让能得知车驾离去，独自追上皇帝于宝鸡；次日孔纬等随后抵达。", "phases": [], "location_name": "宝鸡", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "ab30ca6c-03f0-5c1a-99ea-bc89deb46db1"}, {"title": "孔纬任御史大夫并奉命召百官", "start_year": 886, "end_year": 886, "time_original": "光启二年正月庚寅", "dynasty": "唐", "description": "朝廷任孔纬为御史大夫，命其返召百官，皇帝留宝鸡等待。", "phases": [], "location_name": "宝鸡", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "87b0a11d-99bb-5ca5-9890-a90907cf1a17"}, {"title": "朱玫、李昌符转而与李克用、王重荣合", "start_year": 886, "end_year": 886, "time_original": "田令孜胁驾之后；具体日未载", "dynasty": "唐", "description": "《通鉴》称朱玫、李昌符因不满田令孜且顾忌李克用、王重荣势强，转与二人合。", "phases": [], "location_name": null, "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "原文未给单一地点。", "status": "draft", "id": "1fa917b5-6b6e-58b2-ae6f-87448e5e0c94"}, {"title": "朱玫奉召领兵至凤翔", "start_year": 886, "end_year": 886, "time_original": "光启二年正月癸巳", "dynasty": "唐", "description": "萧遘通过李松年召朱玫迎车驾；癸巳朱玫率步骑五千抵凤翔。", "phases": [], "location_name": "凤翔", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "6c1817ea-04b9-5e08-85b7-ffa751ade0ec"}, {"title": "孔纬催百官赴行在", "start_year": 886, "end_year": 886, "time_original": "光启二年正月癸巳后；具体日未载", "dynasty": "唐", "description": "孔纬敦促百官前往皇帝行在；萧遘、裴澈以田令孜随驾为由称病未往。孔纬后来请求李昌符派骑兵护送，李昌符允之。", "phases": [], "location_name": "凤翔", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "3c826cab-18d2-5f61-bc11-f11d4acd622f"}, {"title": "瑄宁、凤翔兵在潘氏追击车驾", "start_year": 886, "end_year": 886, "time_original": "光启二年正月后条；具体日未载", "dynasty": "唐", "description": "原文作“瑄宁、凤翔兵”追逼车驾，于潘氏击败神策指挥使杨晟；“瑄宁”地军名待校。", "phases": [], "location_name": "潘氏", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "0f98e022-81d0-50ac-ac77-c02746ac47e8"}, {"title": "朝廷置感义军，命杨晟守散关", "start_year": 886, "end_year": 886, "time_original": "潘氏战后；具体日未载", "dynasty": "唐", "description": "田令孜奉皇帝离宝鸡，留禁军守石鼻；朝廷于兴、凤二州置感义军，任杨晟为节度使、守散关。", "phases": [], "location_name": "兴州、凤州、散关", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "e68ac8da-b71e-5958-915f-0bf9eeaa2c3d"}, {"title": "王建、晋晖护送车驾越大散岭", "start_year": 886, "end_year": 886, "time_original": "光启二年正月后条；具体日未载", "dynasty": "唐", "description": "朝廷以王建、晋晖为清道斩斫使。王建领兵在前，携传国宝随驾；李昌符焚阁道，王建扶皇帝越过。", "phases": [], "location_name": "大散岭、散关", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "ee8acb45-c187-5141-bc7a-1b9564be9f08"}, {"title": "朱玫围宝鸡并攻散关未克", "start_year": 886, "end_year": 886, "time_original": "车驾入散关时；具体日未载", "dynasty": "唐", "description": "朱玫围宝鸡，石鼻守军溃散后进攻散关，未能攻下。", "phases": [], "location_name": "宝鸡、散关", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "2340e853-cf2c-56ab-83af-864eb26f6be6"}, {"title": "嗣襄王煴滞留，被朱玫所得", "start_year": 886, "end_year": 886, "time_original": "车驾过散关时；具体日未载", "dynasty": "唐", "description": "嗣襄王煴因病未能随驾，被朱玫得到并带回凤翔。", "phases": [], "location_name": "遵涂驿、凤翔", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "4342a8b3-f21a-527f-afd1-8ab31d28d295"}, {"title": "李克用返回太原", "start_year": 886, "end_year": 886, "time_original": "光启二年正月庚戌", "dynasty": "唐", "description": "李克用返回太原。", "phases": [], "location_name": "太原", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "53b8e880-4920-5749-ac9e-7d3aaf6ddffb"}, {"title": "王重荣、朱政、李昌符再请诛田令孜", "start_year": 886, "end_year": 886, "time_original": "光启二年二月", "dynasty": "唐", "description": "王重荣、朱政、李昌符再次上表请求诛杀田令孜。", "phases": [], "location_name": null, "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "原文未给单一地点。", "status": "draft", "id": "37f50d72-a548-5a0a-83ac-dda97361da9e"}, {"title": "郑从谠任守太傅兼侍中", "start_year": 886, "end_year": 886, "time_original": "光启二年二月条；具体日未载", "dynasty": "唐", "description": "前东都留守郑从谠获任守太傅兼侍中。", "phases": [], "location_name": null, "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "原文未给单一地点。", "status": "draft", "id": "34336999-6eec-5361-b8f0-07ba7f7eed15"}, {"title": "石君涉受朱玫、李昌符命阻车驾", "start_year": 886, "end_year": 886, "time_original": "光启二年二月后至三月前", "dynasty": "唐", "description": "朱玫、李昌符命石君涉设置栅障、焚烧驿舍阻断险要，车驾绕道艰行，邠军在后追逼。", "phases": [], "location_name": "山南西道", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "dee322ad-718e-5096-801e-d6f1be65c33f"}, {"title": "石君涉弃镇归朱玫", "start_year": 886, "end_year": 886, "time_original": "光启二年三月壬午", "dynasty": "唐", "description": "石君涉弃镇，逃归朱玫。", "phases": [], "location_name": "山南西道", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "7f9ca9c5-1083-563f-87ea-12facdd81e42"}]'::jsonb)
